  'play.relic.sig.unique-abbess-censer': { en: 'every spell that hits stains its foe with ink: for 3 seconds it takes 10% more from every hit.', es: 'cada hechizo que acierta mancha al enemigo de tinta: durante 3 segundos recibe un 10% mas de cada golpe.' },
